sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        return;
    }

    var baseManage = g_form.getValue('base_manage');
    var baseUtil = new GlideAjax('x_1593193_bases.BaseUtils');
    baseUtil.addParam('sysparm_name', 'manageValidation');
    baseUtil.addParam('sysparm_baseManage', baseManage);

    baseUtil.getXMLAnswer(function(response) {
        if (response == 'true') {
            g_form.addErrorMessage('The user cannot manage two bases.');
            g_form.setValue('base_manage', '');
        } else {
            g_form.clearMessages();
        }
    });
}
